/**
 * Adds the remaining tokens to the processed tokens list.
 *
 * @param iter An iterator over the remaining tokens
 */
private void gobble(final Iterator<String> iter) {
    if (eatTheRest) {
        while (iter.hasNext()) {
            tokens.add(iter.next());
        }
    }
}
